  const [hoverMenu, setHoverMenu] = useState(null)
  const [hoverAnchor, setHoverAnchor] = useState(null)

  const handleExpand = (section) => {
    if (collapsed) return
    setExpanded(prev => {
      if (prev.includes(section)) {
        return prev.filter(s => s !== section)
      } else {
        return [...prev, section]
      }
    })
  }

